void is_secant_method(char *av[])
{
    double x_zero = 0;
    double x_one = 1;
    double save = 0;
    double result = 0;
    double result_two = 0;
    int limit = 1;

    for (int i = 0; i < 5 || limit == 1; i++) {
        result = (calcul_funct_x(av, x_one) * (x_one - x_zero));
        result_two = (calcul_funct_x(av, x_one) - calcul_funct_x(av, x_zero));
        if (result_two == 0)
